425	func emptyDelivery(d PackageDelivery) bool {
426		return d.ExchangeID == "" && d.Status == "" && d.Digest == "" &&
427			d.CreatedAt.IsZero() && d.Package.PatientID == "" && d.Package.ReceiverID == "" &&
428			len(d.Package.Records) == 0
429	}
