699			t.Fatalf("fetch after deactivate err = %v", err)
700		}
701		conf2, err := f.s.SubmitReceipt(rcv, x2.ID, x2.Digest, ReceiptRejected, "停用前已收到")
702		if err != nil {
703			t.Fatalf("receipt after deactivate: %v", err)
704		}
