854	func TestExchangePersistenceAcrossReopen(t *testing.T) {
855		dir := t.TempDir()
856		clk := &fakeClock{t: time.Date(2026, 4, 1, 8, 0, 0, 0, time.UTC)}
857		open := func() *Store {
858			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
859			if err != nil {
860				t.Fatalf("open: %v", err)
861			}
862			return s
