864	
865		s := open()
866		p, _ := s.RegisterPatient(doc, "持久化交换患者")
867		e, _ := s.AddEncounter(doc, p.ID, time.Time{})
868		rec, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "包内v1")
869		v1, _ := s.ActivateRecord(doc, rec.ID)
870		a, _ := s.Grant(doc, p.ID, rcv.ID, []Scope{{EncounterID: e.ID, Category: Diagnosis}},
871			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))
872	
873		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
874		if err != nil {
