917			t.Fatalf("retry after reopen added audit: %d", n)
918		}
919	
920		// 审计两类事件都在。
921		var creates, receipts int
922		for _, ev := range mustAudit(t, s2, p.ID) {
923			switch ev.Action {
924			case ActionExchanged:
