929		}
930		if creates != 1 || receipts != 1 {
931			t.Fatalf("audit after reopen: creates=%d receipts=%d", creates, receipts)
932		}
933	
934		// 取包路径在重开后同样按当前时间与绑定授权判断（窗口内可取）。
