1	package clinical
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sync"
12		"time"
13	)
14	
15	// dataName 是存放全部业务状态的快照文件名。
16	const dataName = "clinical-data.json"
17	
18	// dataVersion 是快照格式的版本标记，便于将来迁移。
19	const dataVersion = 1
20	
21	// snapshot 是写入磁盘的完整状态。所有业务对象集中在一个文件中，
22	// 采用“临时文件 + 原子改名”整体落盘：成功操作与其审计事件一同保留，
23	// 失败的操作在 mutate 中就已丢弃，不会写出半截状态。
24	type snapshot struct {
25		FormatVersion  int                       `json:"format_version"`
26		Patients       map[string]*Patient       `json:"patients"`
27		Encounters     map[string]*Encounter     `json:"encounters"`
28		Records        map[string]*Record        `json:"records"`
29		Versions       map[string]*Version       `json:"versions"`
30		Authorizations map[string]*Authorization `json:"authorizations"`
31		Exchanges      map[string]*Exchange      `json:"exchanges"`
32		AuditEvents    []*AuditEvent             `json:"audit_events"`
33	}
34	
35	// Clock 决定“发生时间”的来源。生产使用实时时钟；测试可注入固定/可控时钟
36	// 以验证开始、到期、撤回等时间边界。
37	type Clock func() time.Time
38	
39	// Store 是本地临床档案的句柄。数据存放位置由调用方在 Open 时指定。
40	// 同一目录同一时刻只允许一个 Store 打开（通过锁文件互斥）。
41	type Store struct {
42		dir   string
43		clock Clock
44		mu    sync.Mutex
45		lock  *os.File
46		data  *snapshot
47	}
48	
49	// Option 配置 Open 的行为。
50	type Option func(*Store)
51	
52	// WithClock 注入自定义时钟。
53	func WithClock(c Clock) Option {
54		return func(s *Store) { s.clock = c }
55	}
56	
57	// Open 在指定目录打开（必要时创建）本地存储。
58	// 调用方指定数据存放位置；关闭后从同一位置重新打开可看到全部历史，
59	// 到期与否始终按“本次读取时间”重新计算。
60	func Open(dir string, opts ...Option) (*Store, error) {
61		if dir == "" {
62			return nil, fmt.Errorf("%w: empty data directory", ErrInvalidArgument)
63		}
64		if err := os.MkdirAll(dir, 0o755); err != nil {
65			return nil, err
66		}
67	
68		lockPath := filepath.Join(dir, ".clinical.lock")
69		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
70		if err != nil {
71			return nil, err
72		}
73		if err := tryLockFile(lockFile); err != nil {
74			lockFile.Close()
75			return nil, err
76		}
77	
78		s := &Store{dir: dir, clock: time.Now, lock: lockFile}
79		for _, opt := range opts {
80			opt(s)
81		}
82		if s.clock == nil {
83			s.clock = time.Now
84		}
85	
86		if err := s.loadLocked(); err != nil {
87			unlockFile(lockFile)
88			lockFile.Close()
89			return nil, err
90		}
91		return s, nil
92	}
93	
94	func (s *Store) loadLocked() error {
95		path := filepath.Join(s.dir, dataName)
96		raw, err := os.ReadFile(path)
97		if os.IsNotExist(err) {
98			s.data = newSnapshot()
99			return nil
100		}
101		if err != nil {
102			return err
103		}
104		var snap snapshot
105		if err := json.Unmarshal(raw, &snap); err != nil {
106			return err
107		}
108		if snap.FormatVersion != dataVersion {
109			return fmt.Errorf("clinical: unsupported data format version %d", snap.FormatVersion)
110		}
111		ensureMaps(&snap)
112		s.data = &snap
113		return nil
114	}
115	
116	func newSnapshot() *snapshot {
117		snap := &snapshot{FormatVersion: dataVersion}
118		ensureMaps(snap)
119		return snap
120	}
121	
122	func ensureMaps(snap *snapshot) {
123		if snap.Patients == nil {
124			snap.Patients = map[string]*Patient{}
125		}
126		if snap.Encounters == nil {
127			snap.Encounters = map[string]*Encounter{}
128		}
129		if snap.Records == nil {
130			snap.Records = map[string]*Record{}
131		}
132		if snap.Versions == nil {
133			snap.Versions = map[string]*Version{}
134		}
135		if snap.Authorizations == nil {
136			snap.Authorizations = map[string]*Authorization{}
137		}
138		if snap.Exchanges == nil {
139			snap.Exchanges = map[string]*Exchange{}
140		}
141	}
142	
143	// Close 刷新并释放数据目录。Close 后任何业务方法返回 ErrClosed。
144	func (s *Store) Close() error {
145		s.mu.Lock()
146		defer s.mu.Unlock()
147		if s.lock == nil {
148			return ErrClosed
149		}
150		unlockFile(s.lock)
151		err := s.lock.Close()
152		if rmErr := removeLockFile(filepath.Join(s.dir, ".clinical.lock")); rmErr != nil && !os.IsNotExist(rmErr) && err == nil {
153			err = rmErr
154		}
155		s.lock = nil
156		s.data = nil
157		return err
158	}
159	
160	func (s *Store) now() time.Time { return s.clock().UTC() }
161	
162	// errUnchanged 由 mutate 的 fn 返回，表示本次操作只读取了既有结果、
163	// 没有产生任何状态变更（例如幂等重试命中已保存的结果）：直接成功返回，
164	// 不触发落盘。这样重试即使赶上本地保存条件不可用，也能返回原结果。
165	var errUnchanged = errors.New("clinical: no state change")
166	
167	// mutate 在状态的深拷贝上执行业务变更。fn 返回错误时，拷贝连同其中的
168	// 半成品一并丢弃，磁盘与既有业务状态保持原样；fn 返回 nil 时整体原子落盘。
169	// 这样“引用不存在的对象/跨患者混用”等失败都不会留下半条记录。
170	// fn 返回 errUnchanged 时视为成功但不落盘：状态没有任何变化，无需重写数据。
171	func (s *Store) mutate(fn func(*snapshot) error) error {
172		s.mu.Lock()
173		defer s.mu.Unlock()
174		if s.data == nil {
175			return ErrClosed
176		}
177	
178		clone := cloneSnapshot(s.data)
179		if err := fn(clone); err != nil {
180			if errors.Is(err, errUnchanged) {
181				return nil
182			}
183			return err
184		}
185		if err := s.persist(clone); err != nil {
186			return err
187		}
188		s.data = clone
189		return nil
190	}
191	
192	// view 在只读快照上执行查询。
193	func (s *Store) view(fn func(*snapshot) error) error {
194		s.mu.Lock()
195		defer s.mu.Unlock()
196		if s.data == nil {
197			return ErrClosed
198		}
199		return fn(s.data)
200	}
201	
202	func (s *Store) persist(snap *snapshot) error {
203		raw, err := json.MarshalIndent(snap, "", "  ")
204		if err != nil {
205			return err
206		}
207		final := filepath.Join(s.dir, dataName)
208		tmp := filepath.Join(s.dir, dataName+".tmp")
209		if err := os.WriteFile(tmp, raw, 0o600); err != nil {
210			return err
211		}
212		if err := os.Rename(tmp, final); err != nil {
213			_ = os.Remove(tmp)
214			return err
215		}
216		return nil
217	}
218	
219	func cloneSnapshot(in *snapshot) *snapshot {
220		out := &snapshot{
221			FormatVersion:  in.FormatVersion,
222			Patients:       make(map[string]*Patient, len(in.Patients)),
223			Encounters:     make(map[string]*Encounter, len(in.Encounters)),
224			Records:        make(map[string]*Record, len(in.Records)),
225			Versions:       make(map[string]*Version, len(in.Versions)),
226			Authorizations: make(map[string]*Authorization, len(in.Authorizations)),
227			Exchanges:      make(map[string]*Exchange, len(in.Exchanges)),
228			AuditEvents:    make([]*AuditEvent, 0, len(in.AuditEvents)),
229		}
230		for k, v := range in.Patients {
231			p := *v
232			out.Patients[k] = &p
233		}
234		for k, v := range in.Encounters {
235			e := *v
236			out.Encounters[k] = &e
237		}
238		for k, v := range in.Records {
239			r := *v
240			r.Versions = append([]ID(nil), v.Versions...)
241			out.Records[k] = &r
242		}
243		for k, v := range in.Versions {
244			vv := *v
245			out.Versions[k] = &vv
246		}
247		for k, v := range in.Authorizations {
248			a := *v
249			a.Scopes = append([]Scope(nil), v.Scopes...)
250			a.Selections = append([]RecordSelection(nil), v.Selections...)
251			if v.RevokedAt != nil {
252				t := *v.RevokedAt
253				a.RevokedAt = &t
254			}
255			out.Authorizations[k] = &a
256		}
257		for k, x := range in.Exchanges {
258			y := *x
259			y.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
260			if x.Receipt != nil {
261				r := *x.Receipt
262				y.Receipt = &r
263			}
264			out.Exchanges[k] = &y
265		}
266		for _, ev := range in.AuditEvents {
267			e := *ev
268			out.AuditEvents = append(out.AuditEvents, &e)
269		}
270		return out
271	}
