package clinical

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"testing"
)

// TestScratchEmitGolden 仅用于在确定固定摘要时导出规范字节做外部核对：
//
//	go test ./clinical/ -run TestScratchEmitGolden -v
//	sha256sum /tmp/clinical-golden-canonical.json
//
// 规范字节由手写编码器 goldenCanonicalBytes 产生（不经 encoding/json），
// 再由系统 sha256sum 独立复算，避免“产品自证”。
func TestScratchEmitGolden(t *testing.T) {
	raw := goldenCanonicalBytes(digestFixedPkg())
	if err := os.WriteFile("/tmp/clinical-golden-canonical.json", raw, 0o644); err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(raw)
	d := hex.EncodeToString(sum[:])
	d2, raw2 := independentDigest(digestFixedPkg())
	fmt.Printf("BYTES_LEN=%d\n", len(raw))
	fmt.Printf("INDEP_MATCH=%v\n", string(raw2) == string(raw))
	fmt.Printf("PRODUCT_MATCH=%v\n", packageDigest(digestFixedPkg()) == d)
	fmt.Printf("DIGEST=%s\n", d)
	fmt.Printf("BYTES=%s\n", string(raw))
	if d2 != d {
		t.Fatalf("independent %s != hand %s", d2, d)
	}
}

